MATCH (:PlantItem {tag: 'H-1101'})-[:is_drawn_on]->(s:Sheet)
RETURN s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (:PlantItem {tag: 'TK-4802'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:NeedleValve {unit_id: '3'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'EJ-4402B'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (i:PlantItem {tag: 'P-2601B'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'FSLL-42004'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'E-1301'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EA-601'}), (b:PlantItem {tag: 'K-601'}), (d:PlantItem {tag: 'D-601'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE x <> d AND y <> d)+ (b)
       } AS can_flow_without_d

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'LSHH-14011'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'P-4801B'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-1501B'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-1304'}), (b:PlantItem {tag: 'EJ-1302B'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-3101A'})-[:measured_by]->(instrument:PlantItem)
RETURN instrument.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'T-1901'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (i:PlantItem {tag: 'D-2601'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'D-1301'}), (b:PlantItem {tag: 'T-1301'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:GlobeValve:PlantItem {unit_id: '44'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (c:ProcessControlFunction {loop_tag: 'LIC-17001'})-[:send_signal_to*1..]->(a:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-2601'}), (b:PlantItem {tag: 'E-2602'}), (t:PlantItem {tag: 'T-2601'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y <> t)+ (b)
       } AS reachable_without_T_2601

MATCH (v:PlantItem:AngleGlobeValve {unit_id: '44'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-701C'}), (b:PlantItem {tag: 'P-701B'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-4001B'}), (b:PlantItem {tag: 'P-4402A'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-3001'}), (b:PlantItem {tag: 'V-3301'}), (v:PlantItem {tag: 'V-3001'})
WHERE EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y <> v)+ (b)
  RETURN 1
}
RETURN a.tag AS from_tag, b.tag AS to_tag

MATCH (a:PlantItem {tag: 'D-1901'}), (b:PlantItem {tag: 'TK-2704'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'V-2101'}), (b:PlantItem {tag: 'P-3001'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem WHERE x.tag <> 'P-2701B')-[:line_to]->(y:PlantItem WHERE y.tag <> 'P-2701B')){1,} (b)
} AS reachable

MATCH (a:PlantItem {tag: 'P-3601B'}), (b:PlantItem {tag: 'E-4903'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'K-501'}), (b:PlantItem {tag: 'R-401'}), (h:PlantItem {tag: 'H-401'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem WHERE x <> h)-[:line_to]->(y:PlantItem WHERE y <> h))+ (b)
} AS reachable

MATCH (a:PlantItem {tag: 'K-501'}), (b:PlantItem {tag: 'R-401'}), (h:PlantItem {tag: 'H-401'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> h AND y <> h)+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'E-2903'}), (b:PlantItem {tag: 'TK-5301'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'E-3001'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem {loop_tag: 'PAHH-11075'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'E-1502'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (:PlantItem {tag: 'H-1101'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'V-701'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (f:PlantItem {tag: 'F-901A'})-[:line_to*1..]->(v:PlantItem:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-1902B'})
MATCH (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND NOT EXISTS {
    (p)-[:line_to*1..]->(x:PlantItem)-[:line_to*1..]->(v)
    WHERE x <> p AND x <> v AND (x:Valve OR x:Equipment)
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)
WHERE EXISTS {
  MATCH (:PlantItem {tag: 'P-5101A'})-[:line_to*1..]->(v)
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-4301A'})-[:line_to*1..]->(v:PlantItem:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-1902B'})
MATCH (p)-[:line_to*1..]->(v:Valve)
WITH DISTINCT p, v
WHERE NOT EXISTS {
  MATCH (p)-[:line_to*1..]->(x:PlantItem)
  WHERE x <> p AND x <> v AND (x:Valve OR x:Equipment)
    AND EXISTS { (x)-[:line_to*1..]->(v) }
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-701A'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'EA-1101'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem {tag: 'P-101A'}), (v:Valve)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-1902B'}), (v:Valve), (e:Equipment)
WHERE v.category = 'normally open'
  AND EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag **

MATCH (p:PlantItem {tag: 'P-1902B'}), (v:Valve), (e:Equipment)
WHERE v.category = 'normally open'
  AND EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (source:PlantItem {tag: 'F-901A'})
MATCH (valve:Valve)
WHERE EXISTS { (source)-[:line_to*1..]->(valve) }
  AND EXISTS {
    (valve)-[:line_to*1..]->(equipment:Equipment)
    WHERE EXISTS { (source)-[:line_to*1..]->(equipment) }
  }
RETURN DISTINCT valve.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-701B'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS {
    (v)-[:line_to*1..]->(d:Equipment)
    WHERE EXISTS { (p)-[:line_to*1..]->(d) }
  }
  AND toLower(coalesce(v.category, '')) CONTAINS 'normally open'
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(d:PlantItem {tag: 'D-1801'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(tank:PlantItem {tag: 'TK-4101'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;
